import {computeMarkup, mountCompute} from './compute.js';
import {research} from './hardware.js';
import {markup as structureMarkup, mount as mountStructure} from './structure.js';
let disposeStructure=()=>{};
const app=document.querySelector('#app');
const E={official:'官方披露',derived:'计算推导',interpretation:'解释判断',unknown:'未知'};
const labels={layers:'语言层数',hidden:'残差宽度',heads:'注意力头数',attention:'注意力结构',experts:'路由专家总数',topK:'每 token 选中专家',shared:'共享专家等价数量',expertInput:'路由专家输入宽度',expertWidth:'专家中间宽度',denseWidth:'Dense 中间宽度',context:'上下文上限 / token',vocab:'词表大小',visionLayers:'视觉层数',visionHidden:'视觉残差宽度',quantization:'公开权重精度',parameters:'审计逻辑参数',payload:'权重有效载荷'};
const navs=[['','研究主页'],['models','版本库'],['evolution','历史演进'],['technology','技术演进'],['compare','版本比较'],['compute','逐层计算与接口'],['implementation','实现与算子'],['hardware','硬件与部署'],['ascend','Ascend 优化'],['applications','应用场景'],['gallery','图表画廊'],['report','完整报告'],['sources','来源与下载']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=e=>`<span class="evidence ${esc(e)}">${E[e]||E.unknown}</span>`;
const legend=()=>`<div class="legend">证据口径 ${Object.keys(E).map(badge).join('')}</div>`;
const val=(v,k)=>v==null?'未核验 / 未披露':typeof v==='number'?(k==='payload'?`${(v/1e9).toFixed(3)} GB`:v.toLocaleString('en-US')):esc(v);
const fact=(m,k)=>`${val(m.facts[k]?.value,k)} ${badge(m.facts[k]?.evidence||'unknown')}`;
const load=async p=>{const r=await fetch(p);if(!r.ok)throw Error(`无法读取 ${p}（${r.status}）`);return r.json()};
let catalog,family,selected=[],reportCache=new Map(),currentBase='',renderToken=0;
const familyCache=new Map();
const route=p=>`#/family/${family.id}${p?'/'+p:''}`;
const linkModel=id=>route('model/'+id);
const head=(title,desc,eyebrow=family?`${family.name.toUpperCase()} / RESEARCH`:'MODEL RESEARCH')=>`<div class="page-head"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${desc?`<p class="intro">${esc(desc)}</p>`:''}</div>`;
const shell=(body,page)=>`<div class="layout"><aside class="sidebar"><a class="back" href="#/">← 全部研究专题</a><div class="family-label">${esc(family.name)}<small>${esc(family.publisher)}</small></div><nav aria-label="家族研究导航">${navs.map(([p,n],i)=>`<a class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} href="${route(p)}"><i>${String(i+1).padStart(2,'0')}</i>${n}</a>`).join('')}</nav><a class="back" href="model-documents.html?family=Kimi">独立模型 Excel / CSV 下载</a><div class="side-note">研究快照<br>${esc(family.updated)}<br>公开资料 · 可追溯来源</div></aside><main id="content"><div class="crumb"><a href="#/">研究专题</a><span>/</span><a href="${route('')}">${esc(family.name)}</a>${page?`<span>/</span><span>${navs.find(x=>x[0]===page)?.[1]||'版本详情'}</span>`:''}</div>${body}</main></div>`;
function home(){
 const families=catalog.families.map(f=>({ ...f,href:`#/family/${f.id}`,kind:'模型家族',topics:['历史与版本','架构与计算','来源与证据'],counts:[`${f.modelCount} 个名称条目`,`${f.figureCount} 张研究图`]}));
 const reports=(catalog.reports||[]).map(r=>({...r,href:r.path,kind:'组织研究',topics:['主模型与演进','88 仓库分析','昇腾优化'],counts:[`${r.repositoryCount} 个公开仓库`,'完整报告与下载']}));
 const entries=[...families,...reports];
 return `<main id="content"><div class="topline"><div>${head('模型与组织研究','选择模型家族或组织研究专题，了解主模型、技术演进、实现方法与来源证据。','RESEARCH LIBRARY')}</div><span class="pill">${entries.length} 个研究入口</span></div><div class="family-grid">${entries.map(e=>`<a class="family-card" href="${esc(e.href)}"><div class="family-art"><div class="publisher">${esc(e.publisher)} · ${esc(e.kind)}</div><div class="word">${esc(e.name)}</div><div class="ruler">${e.topics.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><div class="family-card-body"><h2>${esc(e.name)} <span aria-hidden="true">↗</span></h2><p>${esc(e.description)}</p><div class="card-foot">${e.counts.map(t=>`<span>${esc(t)}</span>`).join('')}<span>更新 ${esc(e.updated)}</span></div></div></a>`).join('')}</div><p class="index-note">Kimi 按模型家族浏览版本、结构与比较；OpenBMB 按组织研究阅读多个主模型路线和配套项目。仓库数与版本条目数是不同口径，不代表独立模型或架构数量。</p></main>`;
}
function overview(){const ms=family.models;return head(family.name+' 家族研究',family.description,'FAMILY RESEARCH / '+family.name.toUpperCase())+`<div class="stats"><div class="stat"><b>${ms.length}</b><span>历史与公开版本条目</span></div><div class="stat"><b>${ms.filter(m=>m.branch==='主线').length}</b><span>主线公开权重</span></div><div class="stat"><b>${ms.filter(m=>m.branch==='支线').length}</b><span>平行支线权重</span></div><div class="stat"><b>${ms.filter(m=>m.auditPath).length}</b><span>逐张量审计检查点</span></div></div><div class="grid2"><section class="panel feature"><div class="eyebrow">研究结论</div><h2>${esc(family.overview.title)}</h2><p>${esc(family.overview.conclusion)}</p><div class="mini-flow">${family.overview.highlights.map(x=>`<a href="${linkModel(x.id)}">${esc(x.label)}</a>`).join('')}</div><a href="${route('evolution')}">查看完整演进 →</a></section><section class="panel"><div class="eyebrow">阅读路径</div><h2>先看差异，再查证据</h2><p>查某一版的尺寸与精度，进入版本库；研究改变的原因，进入技术演进；要复算结果，查看逐层数据和原始报告。</p><div class="link-row"><a class="button primary" href="${route('models')}">浏览全部版本</a><a class="button" href="${route('compare')}">选择版本比较</a></div></section></div><div class="notice">${esc(family.scope)}</div><h2>先分清五种“大小”</h2>${glossary()}${legend()}`}
function glossary(){return `<dl class="glossary">${[
['总参数','模型保存的完整权重规模。混合专家模型（MoE）每次只使用部分专家，但仍需保存全部专家。'],['激活参数','一个 token 实际选用的参数规模。它与总参数不同，也不等于完整计算量。'],['实际计算','除了线性矩阵乘法，还包括注意力、状态更新、路由及通信。本研究的 FLOPs 代理不是速度实测。'],['权重存储','权重、量化比例因子和元数据占用的字节。低位量化改变存储，不改变逻辑矩阵尺寸。'],['KV 缓存','注意力推理时保存的历史键值。MLA（多头潜在注意力）可用压缩表示；具体布局取决于引擎。'],['KDA 与 AttnRes','KDA（Kimi Delta Attention）用固定状态压缩历史；AttnRes（注意力残差）按内容读取较早层的表示。']].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`}
function modelCard(m){return `<article class="model-card"><div class="branch">${esc(m.branch)} · ${m.auditPath?'权重头审计':m.configPath?'配置核验':'资料记录'}</div><h3><a href="${linkModel(m.id)}">${esc(m.name)}</a></h3><p>${esc(m.summary)}</p><div class="tags">${m.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p>${m.facts.layers.value??'—'} 层 · ${m.facts.context.value?val(m.facts.context.value)+' token':'上下文未核验'}</p><div class="card-actions"><a href="${linkModel(m.id)}">查看详情 →</a><label><input type="checkbox" data-compare="${esc(m.id)}" ${selected.includes(m.id)?'checked':''}>加入比较</label></div></article>`}
function library(){return head('版本库','历史节点、主线与支线分开记录。可按名称、技术或应用方向查找。')+`<div class="filters"><label>搜索版本<input type="search" id="search" placeholder="名称、MLA、INT4、代码…"></label><label>分支<select id="branch"><option value="">全部分支</option>${[...new Set(family.models.map(m=>m.branch))].map(b=>`<option>${esc(b)}</option>`).join('')}</select></label><label>应用方向<select id="tag"><option value="">全部方向</option>${[...new Set(family.models.flatMap(m=>m.tags))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><button id="reset">重置</button></div><div id="model-results" aria-live="polite"></div><div id="compare-bar"></div>`}
function refreshLibrary(){const q=document.querySelector('#search').value.toLowerCase().trim(),b=document.querySelector('#branch').value,t=document.querySelector('#tag').value;const ms=family.models.filter(m=>(!q||JSON.stringify(m).toLowerCase().includes(q))&&(!b||m.branch===b)&&(!t||m.tags.includes(t)));document.querySelector('#model-results').innerHTML=`<div class="count">显示 ${ms.length} / ${family.models.length} 个条目</div><div class="model-grid">${ms.map(modelCard).join('')}</div>${ms.length?'':'<div class="empty">没有符合条件的版本。试试其他关键词，或重置筛选。</div>'}`;refreshBar()}
function refreshBar(){const el=document.querySelector('#compare-bar');if(el)el.innerHTML=selected.length?`<div class="compare-bar"><span>已选择 ${selected.length} 个版本</span><a class="button" href="${route('compare')}">查看比较 →</a></div>`:''}
function compare(){if(!selected.length)selected=family.models.filter(m=>m.auditPath).slice(-3).map(m=>m.id);return head('版本比较','选择任意版本并列核对。未知数据不填零；同尺寸不表示同权重或同能力。')+`<details><summary>选择比较版本（已选 ${selected.length} 个）</summary><div class="model-grid">${family.models.map(m=>`<label><input type="checkbox" data-compare="${esc(m.id)}" ${selected.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</div></details>${legend()}<div id="comparison"></div><p class="notice">权重有效载荷不包含 KV 缓存、激活、通信缓冲和工作区。这里没有统一条件下的速度、价格或能力排名。</p>`}
function refreshComparison(){const ms=family.models.filter(m=>selected.includes(m.id));document.querySelector('#comparison').innerHTML=ms.length?`<div class="table-wrap"><table class="compare-table"><thead><tr><th scope="col">比较维度</th>${ms.map(m=>`<th scope="col"><a href="${linkModel(m.id)}">${esc(m.name)}</a></th>`).join('')}</tr></thead><tbody><tr><th scope="row">主要变化</th>${ms.map(m=>`<td>${esc(m.summary)}</td>`).join('')}</tr>${Object.entries(labels).map(([k,l])=>`<tr><th scope="row">${l}</th>${ms.map(m=>`<td>${fact(m,k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚未选择版本。展开上方列表添加版本。</div>'}
async function detail(id){const m=family.models.find(m=>m.id===id);if(!m)return head('找不到该版本','请从版本库选择已收录的条目。')+`<a class="button" href="${route('models')}">返回版本库</a>`;let h=head(m.name,m.summary,`${family.name.toUpperCase()} / ${m.branch}`)+legend()+`<div class="metrics">${['layers','hidden','context','experts','topK','parameters'].map(k=>`<div class="metric"><span>${labels[k]}</span><b>${m.facts[k].value==null?'—':k==='parameters'?(m.facts[k].value/1e12).toFixed(6)+' T':val(m.facts[k].value)}</b>${badge(m.facts[k].evidence)}</div>`).join('')}</div><div class="link-row"><button data-add="${esc(id)}" class="primary">${selected.includes(id)?'已加入比较':'加入版本比较'}</button><a class="button" href="${route('compare')}">打开比较</a>${m.source?`<a class="button" href="${esc(m.source)}" target="_blank" rel="noopener">官方来源 ↗</a>`:''}</div>`;
 if(family.hardwarePath)h+=`<section class="panel"><h2>研究这版模型如何运行</h2><div class="link-row"><a class="button primary" href="${route('implementation/all/'+id)}">代码与算子</a><a class="button" href="${route('hardware/all/'+id)}">硬件与部署证据</a><a class="button" href="${route('ascend/all/'+id)}">Ascend 验证与优化</a></div><p class="small">结构参数、实现路径和硬件实验分开核验。专题会标明对当前版本的覆盖范围。</p></section>`;
 if(m.computePath)h+=`<div class="link-row"><a class="button primary" href="${m.computePath}">逐层计算流 / Shape / 后端接口 →</a></div>`;
 h+=structureMarkup(m);
 h+=`<details><summary>结构与精度明细</summary><div class="table-wrap"><table><thead><tr><th>字段</th><th>数值 / 说明</th><th>依据</th></tr></thead><tbody>${Object.entries(labels).map(([k,l])=>`<tr><th scope="row">${l}</th><td>${fact(m,k)}</td><td>${m.facts[k].source?`<a href="${esc(m.facts[k].source)}" target="_blank" rel="noopener">来源 ↗</a>`:'未核验'}</td></tr>`).join('')}</tbody></table></div>${m.configPath?`<p class="small"><a href="${m.configPath}" download>下载已保存配置 JSON</a></p>`:''}</details>`;
 if(m.auditPath){const a=await load(m.auditPath);const layers=a.groups.filter(g=>g.group==='decoder');h+=`<section class="panel"><h2>逐层结构与计算</h2><p class="small">共 ${layers.length} 个语言层。蓝色：MLA；绿色：KDA；金色边框：首层 Dense（稠密前馈层）。混合专家层（MoE）只激活部分路由专家。</p><div class="layer-map">${layers.map(g=>`<span class="${g.attention_parameters>4e8?'kda':''} ${g.layer_1based===1?'dense':''}" title="第 ${g.layer_1based} 层 · ${g.logical_parameters.toLocaleString()} 参数">${g.layer_1based}</span>`).join('')}</div><p class="small">计算推导：线性乘法约为 2 × 激活线性参数。未包括注意力核心、递归状态更新、非线性与通信，不能用于预测吞吐。</p><details><summary>展开全部 ${a.groups.length} 个层与组件</summary><div class="table-wrap"><table><thead><tr><th>组件</th><th>层号（1 起）</th><th>逻辑参数</th><th>载荷 GB</th><th>线性 GFLOPs/token</th></tr></thead><tbody>${a.groups.map(g=>`<tr><td>${esc(g.group)}</td><td>${g.layer_1based||'—'}</td><td>${val(g.logical_parameters)}</td><td>${(g.payload_bytes/1e9).toFixed(6)}</td><td>${g.active_linear_parameters!=null?(2*g.active_linear_parameters/1e9).toFixed(6):'—'}</td></tr>`).join('')}</tbody></table></div></details><div class="link-row"><a href="${m.auditPath}" download>下载本版逐层 JSON</a><a href="assets/kimi/${encodeURIComponent(m.name+'-tensor-templates.csv')}" download>下载张量尺寸模板 CSV</a></div><p class="small">固定 revision：<code>${esc(m.revision)}</code></p></section>`}
 else h+=`<div class="notice">${m.configPath?'本版本有配置级核验，未覆盖完整分片权重审计。':'本版本没有同等深度的配置或权重审计。未知尺寸保留为空，不借用相似名称版本的数据。'}</div>`;
 const secs=await getReport();h+=`<h2 style="margin-top:30px">架构与应用解读</h2>${m.sections.map(s=>secs.find(x=>x.id===s)).filter(Boolean).map(s=>`<details><summary>${esc(s.title)}</summary><article class="article">${s.html}</article></details>`).join('')}<a href="${route('report')}">阅读完整报告与计算假设 →</a>`;return h}
function evolution(){return head('历史演进','按研究路线组织，先区分训练变化与结构变化。顺序不代表相邻权重必然直接继承。')+`<div class="notice">${esc(family.historyNote)}</div><h2>历史与主线</h2><div class="timeline">${family.models.filter(m=>m.branch!=='支线').map(m=>`<article><h3><a href="${linkModel(m.id)}">${esc(m.name)}</a></h3><p>${esc(m.summary)}</p><span class="small">${m.facts.layers.value?m.facts.layers.value+' 层 · ':''}${esc(m.facts.attention.value||'架构未核验')}</span></article>`).join('')}</div><h2>平行支线</h2><div class="model-grid">${family.models.filter(m=>m.branch==='支线').map(modelCard).join('')}</div>`}
async function getReport(){if(!reportCache.has(family.id))reportCache.set(family.id,await load(family.reportPath));return reportCache.get(family.id)}
async function technology(topic){const groups=family.technology;const g=groups.find(g=>g.id===topic)||groups[0];if(!g)return head('技术演进','该家族尚未收录技术专题。');const secs=await getReport();return head('技术演进',g.summary)+`<div class="section-nav">${groups.map(x=>`<a class="${x.id===g.id?'active':''}" href="${route('technology/'+x.id)}">${esc(x.title)}</a>`).join('')}</div><details><summary>术语速查：参数、计算、缓存与注意力</summary>${glossary()}</details><article class="article">${secs.find(s=>s.id===g.section)?.html||'暂无研究内容'}</article>`}
function applications(){return head('应用场景','按任务理解版本定位。以下属于研究判断，不是统一条件下的性能排名。')+badge('interpretation')+family.scenarios.map(s=>`<section class="scenario"><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p><div class="link-row">${s.models.map(id=>family.models.find(m=>m.id===id)).filter(Boolean).map(m=>`<a class="button" href="${linkModel(m.id)}">${esc(m.name)}</a>`).join('')}</div><p class="boundary">比较边界：${esc(s.boundary)}</p></section>`).join('')}
function gallery(){return head('图表画廊','全家族总览与十张分析图。点击原图查看完整尺寸，标题下保留数据口径。')+`<div class="gallery">${family.figures.map(f=>`<figure><a href="${esc(f.path)}" target="_blank" rel="noopener"><img src="${esc(f.path)}" alt="${esc(f.caption)}" loading="lazy"></a><figcaption><div class="eyebrow">${f.id===0?'FAMILY OVERVIEW':'FIGURE '+String(f.id).padStart(2,'0')}</div><h3>${esc(f.caption)}</h3><p>${esc(f.source)}</p><a href="${esc(f.path)}" download>下载原图 ↓</a></figcaption></figure>`).join('')}</div>`}
async function report(section){const secs=await getReport();const active=section==='all'?null:secs.find(s=>s.id===section)||secs[0];return head('完整研究报告','报告正文已整合进网站。可逐章阅读或载入全文；原版 HTML、Markdown 与数据附件保留下载。')+`<div class="report-layout"><nav class="report-toc" aria-label="报告章节"><a class="${!active?'active':''}" href="${route('report/all')}">全部章节</a>${secs.map(s=>`<a class="${active?.id===s.id?'active':''}" href="${route('report/'+s.id)}">${esc(s.title)}</a>`).join('')}</nav><article class="article">${(active?[active]:secs).map(s=>s.html).join('')}</article></div>`}
function sources(){return head('来源与下载','保存官方来源、固定版本记录与全部研究附件。大体积张量清单仅在主动下载时传输。')+legend()+`<section class="panel"><h2>审计范围与限制</h2><p>${esc(family.auditNote)}</p><p class="small">${esc(family.limitations)}所有数据是 ${esc(family.updated)} 的研究快照。</p><a href="${esc(family.officialDirectory)}" target="_blank" rel="noopener">官方模型目录 ↗</a></section><details><summary>逐版本官方来源与固定 revision</summary><ul class="source-list">${family.models.map(m=>`<li>${m.source?`<a href="${esc(m.source)}" target="_blank" rel="noopener">${esc(m.name)} ↗</a>`:esc(m.name)+' · 原始来源尚未核验'}<code>${m.revision?'权重审计 revision: '+esc(m.revision):'无固定权重审计 revision'}</code></li>`).join('')}</ul></details><h2>完整附件</h2><div class="filters"><label>筛选下载<input id="download-search" type="search" placeholder="CSV、报告、总览、zip…"></label></div><div id="downloads" class="downloads"></div>`}
function refreshDownloads(){const q=document.querySelector('#download-search').value.toLowerCase();const fs=family.downloads.filter(f=>f.name.toLowerCase().includes(q));document.querySelector('#downloads').innerHTML=fs.map(f=>`<div class="download"><div><a href="${esc(f.path)}" download>${esc(f.name)} ↓</a><details><summary class="small">SHA-256</summary><code class="small" style="overflow-wrap:anywhere">${f.sha256}</code></details></div><small>${f.bytes>1e6?(f.bytes/1e6).toFixed(2)+' MB':(f.bytes/1e3).toFixed(1)+' KB'}</small></div>`).join('')||'<div class="empty">没有符合条件的附件。</div>'}
async function render(){disposeStructure();disposeStructure=()=>{};const token=++renderToken;const p=location.hash.replace(/^#\/?/,'').split('/').map(decodeURIComponent);try{catalog??=await load('data/catalog.json');if(p[0]!=='family'){app.innerHTML=home();document.title='模型与组织研究 · 模型研究图谱';return}const f=catalog.families.find(f=>f.id===p[1]);if(!f){app.innerHTML='<main id="content">'+head('找不到该模型家族','请返回目录选择已收录的家族。')+'<a href="#/">返回模型家族</a></main>';return}if(!familyCache.has(f.id))familyCache.set(f.id,await load(f.path));family=familyCache.get(f.id);if(currentBase!==f.id){selected=[];currentBase=f.id}let page=p[2]||'',body;switch(page){case '':body=overview();break;case 'models':body=library();break;case 'model':body=await detail(p[3]);break;case 'evolution':body=evolution();break;case 'technology':body=await technology(p[3]);break;case 'compare':body=compare();break;case 'applications':body=applications();break;case 'gallery':body=gallery();break;case 'compute':body=await computeMarkup(family,p[3],p[4]);break;case 'implementation':case 'hardware':case 'ascend':body=await research(family,page,p[3],p[4]);break;case 'report':body=await report(p[3]);break;case 'sources':body=sources();break;default:body=head('页面不存在','请使用家族研究导航选择页面。')}if(token!==renderToken)return;app.innerHTML=shell(body,page);document.title=(navs.find(n=>n[0]===page)?.[1]||'版本详情')+' · '+family.name+' · 模型研究图谱';if(page==='compute')mountCompute(family);if(page==='models'){refreshLibrary();for(const id of ['search','branch','tag'])document.querySelector('#'+id).addEventListener('input',refreshLibrary);document.querySelector('#reset').onclick=()=>{for(const id of ['search','branch','tag'])document.querySelector('#'+id).value='';refreshLibrary()}}if(page==='compare')refreshComparison();if(page==='sources'){refreshDownloads();document.querySelector('#download-search').oninput=refreshDownloads}if(page==='model'){const m=family.models.find(m=>m.id===p[3]);if(m)disposeStructure=await mountStructure(m)}window.scrollTo(0,0)}catch(e){if(token===renderToken)app.innerHTML=`<main class="error"><h1>资料暂时无法读取</h1><p>${esc(e.message)}</p><button onclick="location.reload()">重新载入</button><p>请通过本地预览服务打开，避免直接使用 file:// 路径。</p></main>`}}
app.addEventListener('change',e=>{const id=e.target.dataset.compare;if(!id)return;selected=e.target.checked?[...new Set([...selected,id])]:selected.filter(x=>x!==id);refreshBar();if(document.querySelector('#comparison')){refreshComparison();const sum=document.querySelector('details summary');if(sum)sum.textContent=`选择比较版本（已选 ${selected.length} 个）`}});
app.addEventListener('click',e=>{const id=e.target.dataset.add;if(id){selected=[...new Set([...selected,id])];e.target.textContent='已加入比较'}});
window.addEventListener('hashchange',render);render();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const main=document.querySelector('#content');if(main){main.setAttribute('tabindex','-1');main.focus();main.scrollIntoView()}});
